"""Guion tecnico de «Por que El Corte Ingles NO puede quebrar» — planos libres.

    python corte_ingles.py            -> vox/corte_ingles.spec.json

Los numeros de fragmento son los de la locucion (79). Fuentes: config/guion_corte_ingles.md.
"""
from planos import *

MARCA = {"nombre": "EL CORTE INGLES", "color": "#14683E", "claro": "#EAF3E4", "oscuro": "#0C2B1C", "acento": "#FFD95A"}
G = Guion("corte_ingles", MARCA)
PL, CA, MESA, GOB = "f_planta", "f_calle", "calculator_papers", "government_building"


def P(de, pasos, items, clips=None, **k):
    if clips == [PL] and "luz" not in k:
        k["luz"] = 0.6
    if clips == [CA]:
        P.n += 1
        clips = [(CA, "f_paseo", "aerial_town_avenue")[P.n % 3]]
        k.setdefault("luz", 0.66)
    G.plano(de, pasos, items, clips=clips, **k)


